#!/bin/bash
# Compilation by nvc++ -acc=gpu of a behaviour generated by MFront with the
# openacc backend (DefaultGenericSaintVenantKirchhoffElasticity of the tests
# of the generic-parallel interface), with the memory modes given as
# arguments (mem:managed mem:unified by default). Uses the MFront and the
# headers installed by the prototype (install/tfel-mmm-gpu). Compilation
# only, without GPU. The sources and objects are written in
# scratch/reproducers/nvhpc-openacc-managed-global.
# usage: run.sh [memory modes...]
set -u
here=$(cd "$(dirname "$0")" && pwd)
P=$(cd "$here/../.." && pwd)
TFEL=$P/install/tfel-mmm-gpu
NVCXX=${NVCXX:-nvc++}
out="$P/scratch/reproducers/nvhpc-openacc-managed-global"
behaviour=DefaultGenericSaintVenantKirchhoffElasticity
modes=${*:-mem:managed mem:unified}
mkdir -p "$out" && cd "$out" || exit 1
export LD_LIBRARY_PATH=$TFEL/lib:${LD_LIBRARY_PATH:-}
printf 'interfaces_options: {\n  generic-parallel: {\n    backend: "openacc"\n  }\n}\n' \
  > openacc.json
"$TFEL/bin/mfront" --interface=generic-parallel --configuration-file=openacc.json \
  "$P/tfel/test-suite/behaviours/generic-parallel/$behaviour.mfront" \
  > mfront.log 2>&1 || { echo "generation failed (see $out/mfront.log)"; exit 1; }
status=0
for mode in $modes; do
  log="compile-$mode.log"
  if "$NVCXX" -O2 -acc=gpu -gpu="$mode" -std=c++20 -fPIC -DNDEBUG \
    -Iinclude -I"$TFEL/include" \
    -c "src/$behaviour-generic-parallel-openacc.cxx" -o "$behaviour-$mode.o" \
    > "$log" 2>&1; then
    echo "-gpu=$mode: compiled"
  else
    echo "-gpu=$mode: failed: $(grep -m1 'undefined value' "$log")"
    status=1
  fi
done
exit $status
